import type { ContentPack } from '../types';
import { lesson, M, Nq, TF } from '../lib';

const P: ContentPack = {
  '4P-CM-1': lesson(['El paisaje es el aspecto de un lugar. Puede ser natural (sin cambios de las personas) o humanizado (con casas, carreteras, cultivos, fábricas).|El paisatge és l’aspecte d’un lloc. Pot ser natural (sense canvis de les persones) o humanitzat (amb cases, carreteres, cultius, fàbriques).|A landscape is what a place looks like. It can be natural (unchanged by people) or human-made (with houses, roads, crops, factories).', 'Las personas transformamos el paisaje. Hacerlo de forma sostenible es no gastar más recursos de los que la naturaleza puede reponer.|Les persones transformem el paisatge. Fer-ho de manera sostenible és no gastar més recursos dels que la natura pot reposar.|People change landscapes. Doing it sustainably means not using more resources than nature can replace.'],
    'Un campo de naranjos, ¿es un paisaje natural o humanizado?|Un camp de tarongers, és un paisatge natural o humanitzat?|Is an orange grove a natural or human-made landscape?', ['Los naranjos los han plantado personas en filas.|Els tarongers els han plantats persones en files.|People planted the orange trees in rows.', 'Es un paisaje humanizado (agrario).|És un paisatge humanitzat (agrari).|It is a human-made (farming) landscape.'], [
    M('Una selva sin carreteras ni casas es un paisaje…|Una selva sense carreteres ni cases és un paisatge…|A jungle with no roads or houses is a… landscape', 'natural|natural|natural', ['humanizado|humanitzat|human-made', 'urbano|urbà|urban'], 'Las personas no lo han cambiado.|Les persones no l’han canviat.|People have not changed it.'),
    M('Una ciudad es un paisaje…|Una ciutat és un paisatge…|A city is a… landscape', 'humanizado|humanitzat|human-made', ['natural|natural|natural'], 'Está lleno de construcciones.|Està ple de construccions.|It is full of buildings.'),
    M('¿Qué acción daña el paisaje?|Quina acció fa malbé el paisatge?|Which action damages the landscape?', 'tirar residuos en el monte|tirar residus a la muntanya|dumping rubbish in the countryside', ['plantar árboles|plantar arbres|planting trees', 'limpiar una playa|netejar una platja|cleaning a beach'], 'Los residuos contaminan.|Els residus contaminen.|Rubbish pollutes.'),
    TF('El desarrollo sostenible cuida que las personas del futuro también tengan recursos.|El desenvolupament sostenible cuida que les persones del futur també tinguen recursos.|Sustainable development makes sure people in the future have resources too.', true, 'Es usar sin agotar.|És usar sense esgotar.|It means using without using up.'),
    M('¿Qué elemento es humano en un paisaje de montaña?|Quin element és humà en un paisatge de muntanya?|Which element in a mountain landscape is man-made?', 'una carretera|una carretera|a road', ['un río|un riu|a river', 'un pico|un cim|a peak'], 'Lo han construido las personas.|L’han construït les persones.|People built it.'),
    M('¿Qué agente natural cambia el paisaje con el tiempo?|Quin agent natural canvia el paisatge amb el temps?|Which natural force changes landscapes over time?', 'el agua de los ríos|l’aigua dels rius|river water', ['los coches|els cotxes|cars', 'las farolas|els fanals|street lamps'], 'El agua desgasta las rocas.|L’aigua desgasta les roques.|Water wears away rock.'),
  ]),
  '4P-CM-2': lesson(['Los órganos son partes del cuerpo con una tarea: el corazón bombea la sangre, los pulmones toman el aire, el estómago digiere, el cerebro controla todo, los riñones limpian la sangre.|Els òrgans són parts del cos amb una tasca: el cor bomba la sang, els pulmons prenen l’aire, l’estómac digerix, el cervell ho controla tot, els ronyons netegen la sang.|Organs are body parts with a job: the heart pumps blood, the lungs take in air, the stomach digests, the brain controls everything, the kidneys clean the blood.'],
    '¿Qué órgano bombea la sangre?|Quin òrgan bomba la sang?|Which organ pumps blood?', ['Late sin parar.|Batega sense parar.|It beats non-stop.', 'El corazón.|El cor.|The heart.'], [
    M('¿Qué órgano toma el oxígeno del aire?|Quin òrgan pren l’oxigen de l’aire?|Which organ takes oxygen from the air?', 'los pulmones|els pulmons|the lungs', ['el estómago|l’estómac|the stomach', 'los riñones|els ronyons|the kidneys'], 'Se llenan al respirar.|S’omplin en respirar.|They fill when you breathe in.'),
    M('¿Qué órgano controla el cuerpo y piensa?|Quin òrgan controla el cos i pensa?|Which organ controls the body and thinks?', 'el cerebro|el cervell|the brain', ['el corazón|el cor|the heart', 'el hígado|el fetge|the liver'], 'Está en la cabeza.|Està en el cap.|It is in your head.'),
    M('¿Dónde se digieren los alimentos?|On es digerixen els aliments?|Where is food digested?', 'en el estómago y el intestino|en l’estómac i l’intestí|in the stomach and intestines', ['en los pulmones|en els pulmons|in the lungs', 'en el corazón|en el cor|in the heart'], 'Forman el aparato digestivo.|Formen l’aparell digestiu.|They make up the digestive system.'),
    M('¿Qué órganos limpian la sangre y forman la orina?|Quins òrgans netegen la sang i formen l’orina?|Which organs clean the blood and make urine?', 'los riñones|els ronyons|the kidneys', ['los pulmones|els pulmons|the lungs', 'los ojos|els ulls|the eyes'], 'Tienen forma de judía.|Tenen forma de mongeta.|They are bean-shaped.'),
    TF('El corazón es un músculo.|El cor és un múscul.|The heart is a muscle.', true, 'Se contrae para empujar la sangre.|Es contrau per a empényer la sang.|It contracts to push the blood.'),
    M('¿Qué hace el corazón más deprisa cuando corres?|Què fa el cor més de pressa quan corres?|What does your heart do faster when you run?', 'latir|bategar|beat', ['dormir|dormir|sleep', 'pararse|parar-se|stop'], 'Los músculos necesitan más oxígeno.|Els músculs necessiten més oxigen.|Your muscles need more oxygen.'),
  ]),
  '4P-CM-3': lesson(['La energía permite que las cosas funcionen y cambien. Hay energía luminosa (luz), sonora (sonido), térmica (calor), eléctrica, de movimiento…|L’energia permet que les coses funcionen i canvien. Hi ha energia lluminosa (llum), sonora (so), tèrmica (calor), elèctrica, de moviment…|Energy makes things work and change. There is light energy, sound energy, thermal energy (heat), electrical energy, movement energy…', 'El calor pasa siempre de los cuerpos calientes a los fríos.|La calor passa sempre dels cossos calents als freds.|Heat always moves from hot things to cold things.'],
    '¿Qué energía da una bombilla encendida?|Quina energia dona una bombeta encesa?|What energy does a lit bulb give out?', ['Ilumina y se calienta.|Il·lumina i s’escalfa.|It shines and gets warm.', 'Energía luminosa y térmica.|Energia lluminosa i tèrmica.|Light and heat energy.'], [
    M('¿Qué energía produce un tambor al golpearlo?|Quina energia produïx un tambor en colpejar-lo?|What energy does a drum make when you hit it?', 'sonora|sonora|sound', ['luminosa|lluminosa|light', 'eléctrica|elèctrica|electrical'], 'Se oye.|Se sent.|You can hear it.'),
    M('Si pones una cuchara en sopa caliente, ¿hacia dónde va el calor?|Si poses una cullera en sopa calenta, cap a on va la calor?|If you put a spoon in hot soup, where does the heat go?', 'de la sopa a la cuchara|de la sopa a la cullera|from the soup to the spoon', ['de la cuchara a la sopa|de la cullera a la sopa|from the spoon to the soup', 'a ningún sitio|a cap lloc|nowhere'], 'El calor va de lo caliente a lo frío.|La calor va del calent al fred.|Heat goes from hot to cold.'),
    M('¿Qué necesita el sonido para viajar?|Què necessita el so per a viatjar?|What does sound need to travel?', 'un medio, como el aire o el agua|un medi, com l’aire o l’aigua|something to travel through, like air or water', ['luz|llum|light', 'nada|res|nothing'], 'En el espacio vacío no hay sonido.|En l’espai buit no hi ha so.|There is no sound in empty space.'),
    TF('La luz viaja en línea recta.|La llum viatja en línia recta.|Light travels in straight lines.', true, 'Por eso se forman sombras.|Per això es formen ombres.|That is why shadows form.'),
    M('¿Cómo se forma una sombra?|Com es forma una ombra?|How is a shadow made?', 'Un objeto opaco tapa la luz|Un objecte opac tapa la llum|An opaque object blocks the light', ['El objeto se pone negro|L’objecte es posa negre|The object turns black', 'Hace frío|Fa fred|It gets cold'], 'La luz no atraviesa lo opaco.|La llum no travessa el que és opac.|Light cannot pass through opaque things.'),
    M('¿Qué material deja pasar el calor muy bien?|Quin material deixa passar la calor molt bé?|Which material lets heat through very well?', 'el metal|el metall|metal', ['la lana|la llana|wool', 'el corcho|el suro|cork'], 'Por eso las ollas son de metal.|Per això les olles són de metall.|That is why pans are metal.'),
  ]),
  '4P-CM-4': lesson(['La electricidad es una forma de energía que circula por cables. Un circuito necesita una pila (generador), cables, un interruptor y algo que funcione (bombilla, motor).|L’electricitat és una forma d’energia que circula per cables. Un circuit necessita una pila (generador), cables, un interruptor i alguna cosa que funcione (bombeta, motor).|Electricity is a form of energy that flows through wires. A circuit needs a battery, wires, a switch and something that works (a bulb, a motor).', 'Si el circuito está abierto (cortado), la corriente no pasa.|Si el circuit està obert (tallat), el corrent no passa.|If the circuit is open (broken), current does not flow.'],
    '¿Por qué se apaga la luz al pulsar el interruptor?|Per què s’apaga la llum en prémer l’interruptor?|Why does the light go off when you press the switch?', ['El interruptor abre el circuito.|L’interruptor obri el circuit.|The switch opens the circuit.', 'La corriente deja de pasar y la bombilla se apaga.|El corrent deixa de passar i la bombeta s’apaga.|Current stops and the bulb goes off.'], [
    M('¿Qué parte del circuito da la energía?|Quina part del circuit dona l’energia?|Which part of the circuit provides the energy?', 'la pila|la pila|the battery', ['la bombilla|la bombeta|the bulb', 'el interruptor|l’interruptor|the switch'], 'Es el generador.|És el generador.|It is the power source.'),
    M('¿Qué material es aislante (no deja pasar la corriente)?|Quin material és aïllant (no deixa passar el corrent)?|Which material is an insulator (does not let current through)?', 'el plástico|el plàstic|plastic', ['el cobre|el coure|copper', 'el aluminio|l’alumini|aluminium'], 'Por eso recubre los cables.|Per això recobrix els cables.|That is why it coats wires.'),
    M('Si un cable del circuito está cortado, ¿qué pasa?|Si un cable del circuit està tallat, què passa?|If a wire in the circuit is cut, what happens?', 'la bombilla no se enciende|la bombeta no s’encén|the bulb does not light', ['la bombilla brilla más|la bombeta brilla més|the bulb shines brighter', 'nada cambia|res canvia|nothing changes'], 'El circuito está abierto.|El circuit està obert.|The circuit is open.'),
    TF('Tocar un enchufe con las manos mojadas es peligroso.|Tocar un endoll amb les mans banyades és perillós.|Touching a socket with wet hands is dangerous.', true, 'El agua conduce la electricidad.|L’aigua conduïx l’electricitat.|Water conducts electricity.'),
    M('¿Para qué sirve el interruptor?|Per a què servix l’interruptor?|What is a switch for?', 'abrir y cerrar el circuito|obrir i tancar el circuit|opening and closing the circuit', ['dar energía|donar energia|giving energy', 'hacer ruido|fer soroll|making noise'], 'Enciende y apaga.|Encén i apaga.|It turns things on and off.'),
    M('¿Qué transforma la electricidad en movimiento?|Què transforma l’electricitat en moviment?|What turns electricity into movement?', 'un motor|un motor|a motor', ['una bombilla|una bombeta|a bulb', 'un timbre|un timbre|a bell'], 'Como el de un ventilador.|Com el d’un ventilador.|Like the one in a fan.'),
  ]),
  '4P-CM-5': lesson(['Los grandes inventos han cambiado la vida: la rueda, la imprenta, la bombilla, el teléfono, las vacunas, el ordenador, internet…|Els grans invents han canviat la vida: la roda, la impremta, la bombeta, el telèfon, les vacunes, l’ordinador, internet…|Great inventions have changed life: the wheel, the printing press, the light bulb, the telephone, vaccines, the computer, the internet…', 'Muchas mujeres inventoras no fueron reconocidas en su época; hoy conocemos su trabajo, como el de Hedy Lamarr (comunicaciones inalámbricas) o Mary Anderson (el limpiaparabrisas).|Moltes dones inventores no van ser reconegudes en la seua època; hui coneixem el seu treball, com el d’Hedy Lamarr (comunicacions sense fil) o Mary Anderson (el netejaparabrisa).|Many women inventors were not recognised in their time; today we know their work, such as Hedy Lamarr (wireless communication) and Mary Anderson (the windscreen wiper).'],
    '¿Qué invento permitió hacer muchos libros a la vez?|Quin invent va permetre fer molts llibres alhora?|Which invention made it possible to produce many books at once?', ['Antes se copiaban a mano.|Abans es copiaven a mà.|Before, they were copied by hand.', 'La imprenta.|La impremta.|The printing press.'], [
    M('¿Qué invento nos permite hablar con alguien que está lejos?|Quin invent ens permet parlar amb algú que està lluny?|Which invention lets us talk to someone far away?', 'el teléfono|el telèfon|the telephone', ['la rueda|la roda|the wheel', 'la imprenta|la impremta|the printing press'], 'Lleva la voz por cables o por ondas.|Porta la veu per cables o per ones.|It carries your voice through wires or waves.'),
    M('¿Qué invento protege de enfermedades como el sarampión?|Quin invent protegix de malalties com el xarampió?|Which invention protects against illnesses like measles?', 'las vacunas|les vacunes|vaccines', ['la bombilla|la bombeta|the light bulb', 'el reloj|el rellotge|the clock'], 'Han salvado millones de vidas.|Han salvat milions de vides.|They have saved millions of lives.'),
    M('¿Qué inventó Mary Anderson?|Què va inventar Mary Anderson?|What did Mary Anderson invent?', 'el limpiaparabrisas|el netejaparabrisa|the windscreen wiper', ['el teléfono|el telèfon|the telephone', 'la rueda|la roda|the wheel'], 'Lo ideó viendo la nieve en un tranvía.|El va idear veient la neu en un tramvia.|She thought of it watching snow on a tram.'),
    TF('La rueda es uno de los inventos más antiguos.|La roda és un dels invents més antics.|The wheel is one of the oldest inventions.', true, 'Tiene más de 5 000 años.|Té més de 5 000 anys.|It is over 5,000 years old.'),
    M('¿Qué invento conecta ordenadores de todo el mundo?|Quin invent connecta ordinadors de tot el món?|Which invention connects computers all over the world?', 'internet|internet|the internet', ['la imprenta|la impremta|the printing press', 'la brújula|la brúixola|the compass'], 'Es una gran red.|És una gran xarxa.|It is a huge network.'),
    M('¿Qué invento permitió tener luz por la noche sin fuego?|Quin invent va permetre tindre llum de nit sense foc?|Which invention gave light at night without fire?', 'la bombilla|la bombeta|the light bulb', ['la vacuna|la vacuna|the vaccine', 'el telescopio|el telescopi|the telescope'], 'Funciona con electricidad.|Funciona amb electricitat.|It runs on electricity.'),
  ]),
  '4P-CM-6': lesson(['La ciencia y la tecnología pueden ayudar a cuidar el planeta: paneles solares, coches eléctricos, reciclaje, ahorro de agua y bombillas de bajo consumo.|La ciència i la tecnologia poden ajudar a cuidar el planeta: plaques solars, cotxes elèctrics, reciclatge, estalvi d’aigua i bombetes de baix consum.|Science and technology can help look after the planet: solar panels, electric cars, recycling, saving water and low-energy bulbs.'],
    '¿Qué invento aprovecha la luz del sol para hacer electricidad?|Quin invent aprofita la llum del sol per a fer electricitat?|Which invention uses sunlight to make electricity?', ['El sol es una fuente de energía que no se acaba.|El sol és una font d’energia que no s’acaba.|The sun is an energy source that does not run out.', 'El panel solar.|La placa solar.|The solar panel.'], [
    M('¿Qué bombilla gasta menos energía?|Quina bombeta gasta menys energia?|Which bulb uses less energy?', 'la LED|la LED|an LED bulb', ['la incandescente antigua|la incandescent antiga|an old incandescent bulb', 'todas igual|totes igual|they are all the same'], 'Da la misma luz con menos electricidad.|Dona la mateixa llum amb menys electricitat.|It gives the same light using less electricity.'),
    M('¿Qué transporte contamina menos en la ciudad?|Quin transport contamina menys en la ciutat?|Which transport pollutes least in a city?', 'la bicicleta|la bicicleta|a bicycle', ['un coche viejo de gasolina|un cotxe vell de gasolina|an old petrol car', 'una moto antigua|una moto antiga|an old motorbike'], 'No quema combustible.|No crema combustible.|It burns no fuel.'),
    TF('Los molinos de viento modernos producen electricidad.|Els molins de vent moderns produïxen electricitat.|Modern wind turbines produce electricity.', true, 'Se llaman aerogeneradores.|Es diuen aerogeneradors.|They are called wind turbines.'),
    M('¿Para qué sirve reciclar el plástico?|Per a què servix reciclar el plàstic?|What is the point of recycling plastic?', 'Para fabricar cosas nuevas sin usar más petróleo|Per a fabricar coses noves sense usar més petroli|To make new things without using more oil', ['Para que haya más basura|Perquè hi haja més fem|To make more rubbish', 'Para nada|Per a res|No point'], 'El plástico viene del petróleo.|El plàstic ve del petroli.|Plastic comes from oil.'),
    M('Un grifo con sensor que se cierra solo ayuda a…|Una aixeta amb sensor que es tanca sola ajuda a…|A tap with a sensor that shuts off by itself helps to…', 'ahorrar agua|estalviar aigua|save water', ['gastar más agua|gastar més aigua|use more water', 'calentar el agua|escalfar l’aigua|heat water'], 'No se queda abierto.|No es queda oberta.|It does not stay on.'),
    M('¿Qué es una energía renovable?|Què és una energia renovable?|What is renewable energy?', 'La que no se agota, como la del sol o el viento|La que no s’esgota, com la del sol o el vent|Energy that does not run out, like sun or wind', ['La del petróleo|La del petroli|Oil energy', 'La del carbón|La del carbó|Coal energy'], 'Se renueva sola.|Es renova sola.|It renews itself.'),
  ]),
  '4P-CM-7': lesson(['Para buscar información en internet: usa palabras clave, mira quién ha escrito la página y compara varias fuentes. No todo lo que hay en internet es verdad.|Per a buscar informació a internet: usa paraules clau, mira qui ha escrit la pàgina i compara diverses fonts. No tot el que hi ha a internet és veritat.|To search the internet: use key words, check who wrote the page and compare several sources. Not everything online is true.', 'Busca con un adulto o en buscadores para niños, y no pulses anuncios ni enlaces raros.|Busca amb un adult o en cercadors per a xiquets, i no premes anuncis ni enllaços estranys.|Search with an adult or on child-friendly search engines, and do not click ads or strange links.'],
    'Quieres saber cuánto vive una tortuga. ¿Qué escribes en el buscador?|Vols saber quant viu una tortuga. Què escrius en el cercador?|You want to know how long a tortoise lives. What do you type into the search engine?', ['Uso pocas palabras importantes.|Use poques paraules importants.|I use a few important words.', '«tortuga años de vida».|«tortuga anys de vida».|"tortoise lifespan".'], [
    M('¿Qué página es más fiable para un trabajo de ciencias?|Quina pàgina és més fiable per a un treball de ciències?|Which website is more reliable for a science project?', 'la de un museo de ciencias|la d’un museu de ciències|a science museum’s', ['un comentario anónimo|un comentari anònim|an anonymous comment', 'un anuncio|un anunci|an advert'], 'Fíjate en quién la escribe.|Fixa’t en qui l’escriu.|Look at who wrote it.'),
    M('¿Qué haces si dos páginas dicen cosas distintas?|Què fas si dues pàgines diuen coses diferents?|What do you do if two websites disagree?', 'Busco una tercera fuente fiable|Busque una tercera font fiable|Look for a third reliable source', ['Me creo la primera|Em crec la primera|Believe the first one', 'Me invento la respuesta|M’invente la resposta|Make up the answer'], 'Contrastar es comparar fuentes.|Contrastar és comparar fonts.|Checking means comparing sources.'),
    TF('Todo lo que aparece en internet es verdad.|Tot el que apareix a internet és veritat.|Everything on the internet is true.', false, 'Cualquiera puede publicar.|Qualsevol pot publicar.|Anyone can post.'),
    M('Mientras buscas, aparece un anuncio: «¡Pulsa y gana!». ¿Qué haces?|Mentre busques, apareix un anunci: «Prem i guanya!». Què fas?|While searching, an advert pops up: "Click and win!". What do you do?', 'Lo cierro sin pulsar|El tanque sense prémer|Close it without clicking', ['Pulso|Prem|Click it', 'Doy mis datos|Done les meues dades|Give my details'], 'Suelen ser trampas.|Solen ser paranys.|They are usually traps.'),
    M('¿Qué son las palabras clave?|Què són les paraules clau?|What are key words?', 'Las palabras más importantes de lo que buscas|Les paraules més importants del que busques|The most important words of what you are looking for', ['Contraseñas|Contrasenyes|Passwords', 'Palabras largas|Paraules llargues|Long words'], 'Ayudan al buscador a encontrar lo que quieres.|Ajuden el cercador a trobar el que vols.|They help the search engine find what you want.'),
    M('Al usar información de una web en un trabajo, ¿qué debes hacer?|En usar informació d’una web en un treball, què has de fer?|When you use information from a website in a project, what should you do?', 'Decir de dónde la has sacado|Dir d’on l’has treta|Say where you got it from', ['Copiarla sin decir nada|Copiar-la sense dir res|Copy it without saying', 'Cambiar las fechas|Canviar les dates|Change the dates'], 'Citar la fuente es respetar al autor.|Citar la font és respectar l’autor.|Citing the source respects the author.'),
  ]),
  '4P-CM-8': lesson(['Cuando un aparato no funciona, antes de pedir ayuda podemos comprobar cosas sencillas: ¿está enchufado?, ¿tiene batería?, ¿está encendido?, ¿hay que reiniciarlo?|Quan un aparell no funciona, abans de demanar ajuda podem comprovar coses senzilles: està endollat?, té bateria?, està encés?, cal reiniciar-lo?|When a device does not work, before asking for help we can check simple things: is it plugged in? Is it charged? Is it switched on? Does it need restarting?'],
    'La tableta no se enciende. ¿Qué compruebas primero?|La tauleta no s’encén. Què comproves primer?|The tablet will not turn on. What do you check first?', ['Lo más sencillo: la energía.|El més senzill: l’energia.|The simplest thing: power.', 'Si tiene batería: la pongo a cargar.|Si té bateria: la pose a carregar.|Whether it is charged: I plug it in to charge.'], [
    M('El ratón del ordenador no mueve la flecha. ¿Qué miras?|El ratolí de l’ordinador no mou la fletxa. Què mires?|The computer mouse does not move the pointer. What do you check?', 'Si está bien conectado o tiene pilas|Si està ben connectat o té piles|Whether it is plugged in or has batteries', ['Si está sucia la pantalla|Si està bruta la pantalla|Whether the screen is dirty', 'El color del ratón|El color del ratolí|The colour of the mouse'], 'Empieza por la energía y la conexión.|Comença per l’energia i la connexió.|Start with power and connection.'),
    M('Un programa se ha quedado bloqueado. ¿Qué puedes hacer?|Un programa s’ha quedat bloquejat. Què pots fer?|A program has frozen. What can you do?', 'Cerrarlo y volver a abrirlo|Tancar-lo i tornar a obrir-lo|Close it and open it again', ['Golpear la pantalla|Colpejar la pantalla|Hit the screen', 'Echar agua|Tirar aigua|Pour water on it'], 'Reiniciar soluciona muchos problemas.|Reiniciar soluciona molts problemes.|Restarting fixes many problems.'),
    M('No se oye el vídeo. ¿Qué compruebas?|No se sent el vídeo. Què comproves?|You cannot hear the video. What do you check?', 'El volumen y si está silenciado|El volum i si està silenciat|The volume and whether it is muted', ['El brillo|La brillantor|The brightness', 'La hora|L’hora|The time'], 'Busca el altavoz con una raya.|Busca l’altaveu amb una ratlla.|Look for the speaker with a line through it.'),
    TF('Si un aparato echa humo, hay que desenchufarlo y avisar a un adulto.|Si un aparell trau fum, cal desendollar-lo i avisar un adult.|If a device gives off smoke, unplug it and tell an adult.', true, 'La seguridad va primero.|La seguretat va primer.|Safety first.'),
    M('El ordenador no tiene internet. ¿Qué miras?|L’ordinador no té internet. Què mires?|The computer has no internet. What do you check?', 'Si el wifi está activado|Si el wifi està activat|Whether wifi is turned on', ['Si el teclado es nuevo|Si el teclat és nou|Whether the keyboard is new', 'Si la mesa está limpia|Si la taula està neta|Whether the desk is clean'], 'Comprueba la conexión.|Comprova la connexió.|Check the connection.'),
    M('¿Cuándo hay que pedir ayuda a un adulto?|Quan cal demanar ajuda a un adult?|When should you ask an adult for help?', 'Si lo sencillo no funciona o hay peligro|Si el més senzill no funciona o hi ha perill|If the simple checks do not work or there is danger', ['Nunca|Mai|Never', 'Antes de mirar nada|Abans de mirar res|Before checking anything'], 'Primero lo sencillo; luego, ayuda.|Primer el més senzill; després, ajuda.|Simple checks first; then help.'),
  ]),
  '4P-CM-9': lesson(['El bienestar digital es usar las pantallas de forma sana: poco tiempo seguido, descansos, nada de pantallas antes de dormir y combinarlas con juego al aire libre.|El benestar digital és usar les pantalles de manera sana: poc temps seguit, descansos, res de pantalles abans de dormir i combinar-les amb joc a l’aire lliure.|Digital wellbeing means using screens healthily: short spells, breaks, no screens before bed, and mixing them with outdoor play.', 'Si algo en internet te hace sentir mal o alguien te molesta, cuéntaselo a un adulto de confianza.|Si alguna cosa a internet et fa sentir malament o algú et molesta, conta-ho a un adult de confiança.|If something online upsets you or someone bothers you, tell a trusted adult.'],
    'Llevas una hora jugando a la consola. ¿Qué haces?|Portes una hora jugant a la consola. Què fas?|You have been playing on the console for an hour. What do you do?', ['Mucho tiempo seguido cansa la vista y el cuerpo.|Molt de temps seguit cansa la vista i el cos.|Long spells tire your eyes and body.', 'Hago un descanso y me muevo.|Faig un descans i em moc.|I take a break and move about.'], [
    M('¿Qué es mejor antes de dormir?|Què és millor abans de dormir?|What is best before bed?', 'Apagar las pantallas un rato antes|Apagar les pantalles una estona abans|Switch screens off a while before', ['Ver vídeos en la cama|Veure vídeos al llit|Watch videos in bed', 'Jugar en el móvil|Jugar en el mòbil|Play on a phone'], 'La luz de las pantallas quita el sueño.|La llum de les pantalles lleva la son.|Screen light keeps you awake.'),
    M('Alguien te envía mensajes que te hacen sentir mal. ¿Qué haces?|Algú t’envia missatges que et fan sentir malament. Què fas?|Someone sends you messages that upset you. What do you do?', 'Lo cuento a un adulto de confianza|Ho conte a un adult de confiança|Tell a trusted adult', ['Contesto con insultos|Contesto amb insults|Reply with insults', 'Me lo guardo|M’ho guarde|Keep it to myself'], 'Pedir ayuda es valiente.|Demanar ajuda és valent.|Asking for help is brave.'),
    TF('Pasar todo el día con pantallas es bueno para la salud.|Passar tot el dia amb pantalles és bo per a la salut.|Spending all day on screens is good for your health.', false, 'Hace falta moverse, jugar y descansar la vista.|Cal moure’s, jugar i descansar la vista.|You need to move, play and rest your eyes.'),
    M('¿Qué ayuda a cuidar la vista con las pantallas?|Què ajuda a cuidar la vista amb les pantalles?|What helps protect your eyes when using screens?', 'Mirar a lo lejos cada cierto tiempo|Mirar lluny cada cert temps|Look into the distance every so often', ['Acercar mucho la pantalla|Acostar molt la pantalla|Hold the screen very close', 'Usarla a oscuras|Usar-la a les fosques|Use it in the dark'], 'Los ojos descansan al mirar lejos.|Els ulls descansen en mirar lluny.|Your eyes rest when you look far away.'),
    M('¿Qué actividad equilibra el tiempo de pantallas?|Quina activitat equilibra el temps de pantalles?|Which activity balances screen time?', 'jugar al aire libre|jugar a l’aire lliure|playing outdoors', ['otra pantalla|una altra pantalla|another screen', 'no dormir|no dormir|not sleeping'], 'Moverse es salud.|Moure’s és salut.|Moving is healthy.'),
    M('Un amigo comparte una foto tuya sin permiso. ¿Qué le dices?|Un amic comparteix una foto teua sense permís. Què li dius?|A friend shares a photo of you without asking. What do you say?', 'Que la borre y que pida permiso|Que l’esborre i que demane permís|Ask them to delete it and ask first next time', ['Nada|Res|Nothing', 'Que comparta más|Que en compartisca més|Ask them to share more'], 'Las fotos de una persona son suyas.|Les fotos d’una persona són seues.|Photos of someone belong to them.'),
  ]),
  '4P-CM-10': lesson(['En un proyecto de diseño con dispositivos (un robot, una placa con luces) seguimos pasos: definir el problema, idear, planificar con un boceto, construir, programar, probar y mejorar.|En un projecte de disseny amb dispositius (un robot, una placa amb llums) seguim passos: definir el problema, idear, planificar amb un esbós, construir, programar, provar i millorar.|In a design project with devices (a robot, a board with lights) we follow steps: define the problem, generate ideas, plan with a sketch, build, program, test and improve.', 'Trabajar en equipo reparte tareas: quien diseña, quien programa, quien prueba.|Treballar en equip reparteix tasques: qui dissenya, qui programa, qui prova.|Teamwork shares out jobs: designer, programmer, tester.'],
    'Queremos un robot que avise si alguien abre la puerta. ¿Qué paso va antes de construir?|Volem un robot que avise si algú obri la porta. Quin pas va abans de construir?|We want a robot that warns when someone opens the door. Which step comes before building?', ['Primero pensamos ideas y elegimos una.|Primer pensem idees i en triem una.|First we think of ideas and pick one.', 'Hacemos un boceto con las piezas.|Fem un esbós amb les peces.|We draw a sketch with the parts.'], [
    M('¿Qué es un boceto?|Què és un esbós?|What is a sketch?', 'un dibujo rápido de la idea|un dibuix ràpid de la idea|a quick drawing of the idea', ['el producto terminado|el producte acabat|the finished product', 'una pieza del robot|una peça del robot|a robot part'], 'Sirve para planificar.|Servix per a planificar.|It is for planning.'),
    M('Después de construir y programar, ¿qué viene?|Després de construir i programar, què ve?|After building and programming, what comes next?', 'probar y mejorar|provar i millorar|testing and improving', ['tirarlo|tirar-lo|throwing it away', 'empezar otro sin probar|començar-ne un altre sense provar|starting another without testing'], 'Así se corrigen los fallos.|Així es corregixen els errors.|That is how faults get fixed.'),
    M('¿Qué pieza detecta si hay luz o movimiento?|Quina peça detecta si hi ha llum o moviment?|Which part detects light or movement?', 'un sensor|un sensor|a sensor', ['un tornillo|un cargol|a screw', 'una rueda|una roda|a wheel'], 'Los sensores «notan» cosas.|Els sensors «noten» coses.|Sensors "sense" things.'),
    TF('En un equipo cada persona puede tener una tarea distinta.|En un equip cada persona pot tindre una tasca diferent.|In a team each person can have a different job.', true, 'Repartir tareas ayuda a avanzar.|Repartir tasques ajuda a avançar.|Sharing jobs helps progress.'),
    M('¿Qué material es buena idea para la carcasa de un prototipo?|Quin material és bona idea per a la carcassa d’un prototip?|What is a good material for a prototype’s case?', 'cartón reciclado|cartó reciclat|recycled cardboard', ['vidrio roto|vidre trencat|broken glass', 'nada|res|nothing'], 'Es fácil de cortar y barato.|És fàcil de tallar i barat.|It is easy to cut and cheap.'),
    M('El robot no hace lo esperado. ¿Qué haces?|El robot no fa el que s’esperava. Què fas?|The robot does not do what you expected. What do you do?', 'Revisar el programa paso a paso|Revisar el programa pas a pas|Check the program step by step', ['Cambiar todo a la vez|Canviar-ho tot alhora|Change everything at once', 'Rendirse|Rendir-se|Give up'], 'Buscar el error de forma ordenada.|Buscar l’error de manera ordenada.|Look for the mistake in an orderly way.'),
  ]),
  '4P-CM-11': lesson(['El clima es el tiempo que suele hacer en un lugar a lo largo de muchos años. Depende de la latitud (distancia al ecuador), la altitud, la cercanía al mar y el relieve.|El clima és el temps que sol fer en un lloc al llarg de molts anys. Depén de la latitud (distància a l’equador), l’altitud, la proximitat a la mar i el relleu.|Climate is the usual weather in a place over many years. It depends on latitude (distance from the equator), altitude, nearness to the sea and landforms.', 'Cuanto más alto, más frío; cerca del mar, las temperaturas son más suaves.|Com més alt, més fred; prop de la mar, les temperatures són més suaus.|The higher up, the colder; near the sea, temperatures are milder.'],
    '¿Por qué hace más frío en la cima de una montaña?|Per què fa més fred al cim d’una muntanya?|Why is it colder at the top of a mountain?', ['La temperatura baja con la altura.|La temperatura baixa amb l’altura.|Temperature drops with height.', 'Por la altitud.|Per l’altitud.|Because of the altitude.'], [
    M('¿Qué es el clima?|Què és el clima?|What is climate?', 'el tiempo habitual durante muchos años|el temps habitual durant molts anys|the usual weather over many years', ['el tiempo de hoy|el temps de hui|today’s weather', 'la hora|l’hora|the time'], 'El tiempo es de un día; el clima, de muchos años.|El temps és d’un dia; el clima, de molts anys.|Weather is one day; climate is many years.'),
    M('¿Dónde son más suaves las temperaturas?|On són més suaus les temperatures?|Where are temperatures milder?', 'cerca del mar|prop de la mar|near the sea', ['en el interior lejos del mar|a l’interior lluny de la mar|inland far from the sea', 'en lo alto de una montaña|dalt d’una muntanya|on a mountain top'], 'El mar suaviza el frío y el calor.|La mar suavitza el fred i la calor.|The sea softens cold and heat.'),
    M('¿Dónde hace más calor, en el ecuador o en los polos?|On fa més calor, a l’equador o als pols?|Where is it hotter, at the equator or the poles?', 'en el ecuador|a l’equador|at the equator', ['en los polos|als pols|at the poles'], 'Los rayos del sol llegan más directos.|Els raigs del sol arriben més directes.|The sun’s rays hit more directly.'),
    TF('Valencia, junto al mar, tiene inviernos más suaves que una ciudad del interior.|València, al costat de la mar, té hiverns més suaus que una ciutat de l’interior.|Valencia, by the sea, has milder winters than an inland city.', true, 'El mar suaviza las temperaturas.|La mar suavitza les temperatures.|The sea moderates temperatures.'),
    M('¿Qué acción humana aumenta el calentamiento del planeta?|Quina acció humana augmenta l’escalfament del planeta?|Which human action increases global warming?', 'quemar combustibles fósiles|cremar combustibles fòssils|burning fossil fuels', ['plantar bosques|plantar boscos|planting forests', 'ir en bici|anar amb bici|cycling'], 'Liberan gases de efecto invernadero.|Alliberen gasos d’efecte d’hivernacle.|They release greenhouse gases.'),
    M('¿Qué factor del clima es la distancia al ecuador?|Quin factor del clima és la distància a l’equador?|Which climate factor is distance from the equator?', 'la latitud|la latitud|latitude', ['la altitud|l’altitud|altitude', 'el viento|el vent|wind'], 'Latitud = lejos o cerca del ecuador.|Latitud = lluny o prop de l’equador.|Latitude = far from or near the equator.'),
  ]),
  '4P-CM-12': lesson(['El Sistema Solar está formado por el Sol y todo lo que gira a su alrededor: ocho planetas (Mercurio, Venus, Tierra, Marte, Júpiter, Saturno, Urano y Neptuno), sus satélites, asteroides y cometas.|El sistema solar està format pel Sol i tot el que gira al seu voltant: huit planetes (Mercuri, Venus, Terra, Mart, Júpiter, Saturn, Urà i Neptú), els seus satèl·lits, asteroides i cometes.|The Solar System is the Sun and everything that orbits it: eight planets (Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune), their moons, asteroids and comets.', 'El Sol es una estrella: da luz y calor. La Luna es el satélite de la Tierra.|El Sol és una estrela: dona llum i calor. La Lluna és el satèl·lit de la Terra.|The Sun is a star: it gives light and heat. The Moon is the Earth’s satellite.'],
    '¿Qué planeta es el más grande?|Quin planeta és el més gran?|Which planet is the biggest?', ['Es un gigante de gas.|És un gegant de gas.|It is a gas giant.', 'Júpiter.|Júpiter.|Jupiter.'], [
    Nq('¿Cuántos planetas tiene el Sistema Solar?|Quants planetes té el sistema solar?|How many planets are in the Solar System?', 8, [7, 9, 10], 'Mercurio, Venus, Tierra, Marte, Júpiter, Saturno, Urano y Neptuno.|Mercuri, Venus, Terra, Mart, Júpiter, Saturn, Urà i Neptú.|Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune.'),
    M('¿Qué es el Sol?|Què és el Sol?|What is the Sun?', 'una estrella|una estrela|a star', ['un planeta|un planeta|a planet', 'un satélite|un satèl·lit|a moon'], 'Tiene luz propia.|Té llum pròpia.|It makes its own light.'),
    M('¿Qué planeta está más cerca del Sol?|Quin planeta està més prop del Sol?|Which planet is closest to the Sun?', 'Mercurio|Mercuri|Mercury', ['Neptuno|Neptú|Neptune', 'la Tierra|la Terra|Earth'], 'Es el primero.|És el primer.|It is the first.'),
    M('¿Qué planeta tiene unos anillos muy visibles?|Quin planeta té uns anells molt visibles?|Which planet has very visible rings?', 'Saturno|Saturn|Saturn', ['Marte|Mart|Mars', 'Venus|Venus|Venus'], 'Sus anillos son de hielo y roca.|Els seus anells són de gel i roca.|Its rings are ice and rock.', { visual: { type: 'emoji', rows: ['🪐'], big: true } }),
    M('¿Qué es la Luna?|Què és la Lluna?|What is the Moon?', 'el satélite de la Tierra|el satèl·lit de la Terra|Earth’s satellite', ['una estrella|una estrela|a star', 'un planeta|un planeta|a planet'], 'Gira alrededor de la Tierra.|Gira al voltant de la Terra.|It orbits the Earth.'),
    M('¿Por qué Marte se ve rojizo?|Per què Mart es veu rogenc?|Why does Mars look reddish?', 'Su suelo tiene mucho óxido de hierro|El seu sòl té molt d’òxid de ferro|Its soil has a lot of iron oxide', ['Está ardiendo|Està cremant|It is on fire', 'Está cubierto de fresas|Està cobert de maduixes|It is covered in strawberries'], 'Es como la herrumbre.|És com el rovell.|Like rust.'),
  ]),
  '4P-CM-13': lesson(['La Tierra gira sobre sí misma (rotación) en 24 horas: por eso hay día y noche.|La Terra gira sobre si mateixa (rotació) en 24 hores: per això hi ha dia i nit.|The Earth spins on its axis (rotation) in 24 hours: that is why we have day and night.', 'También gira alrededor del Sol (traslación) en 365 días: un año. Como su eje está inclinado, hay estaciones.|També gira al voltant del Sol (translació) en 365 dies: un any. Com que el seu eix està inclinat, hi ha estacions.|It also travels round the Sun (revolution) in 365 days: one year. Because its axis is tilted, we have seasons.'],
    '¿Por qué hay día y noche?|Per què hi ha dia i nit?|Why are there day and night?', ['La Tierra gira sobre sí misma.|La Terra gira sobre si mateixa.|The Earth spins on its axis.', 'La parte que mira al Sol tiene día; la otra, noche.|La part que mira al Sol té dia; l’altra, nit.|The side facing the Sun has day; the other has night.'], [
    M('¿Cuánto tarda la Tierra en dar una vuelta sobre sí misma?|Quant tarda la Terra a fer una volta sobre si mateixa?|How long does the Earth take to spin once?', '24 horas|24 hores|24 hours', ['365 días|365 dies|365 days', '1 hora|1 hora|1 hour'], 'Es un día entero.|És un dia sencer.|It is one whole day.'),
    M('¿Cómo se llama el movimiento alrededor del Sol?|Com es diu el moviment al voltant del Sol?|What is the movement round the Sun called?', 'traslación|translació|revolution', ['rotación|rotació|rotation', 'erosión|erosió|erosion'], 'Dura un año.|Dura un any.|It takes a year.'),
    Nq('¿Cuántos días dura un año, más o menos?|Quants dies dura un any, més o menys?|About how many days are there in a year?', 365, [30, 100, 24], 'Lo que tarda la Tierra en dar la vuelta al Sol.|El que tarda la Terra a fer la volta al Sol.|How long the Earth takes to go round the Sun.'),
    M('¿Por qué hay estaciones?|Per què hi ha estacions?|Why are there seasons?', 'Por la inclinación del eje de la Tierra|Per la inclinació de l’eix de la Terra|Because the Earth’s axis is tilted', ['Porque el Sol se apaga|Perquè el Sol s’apaga|Because the Sun switches off', 'Por la Luna|Per la Lluna|Because of the Moon'], 'Los rayos llegan más o menos inclinados.|Els raigs arriben més o menys inclinats.|Sunlight arrives at different angles.'),
    TF('La Tierra tiene forma de esfera algo achatada en los polos.|La Terra té forma d’esfera un poc aixafada als pols.|The Earth is a sphere slightly flattened at the poles.', true, 'Se comprobó con fotos desde el espacio.|Es va comprovar amb fotos des de l’espai.|Photos from space confirm it.'),
    M('Cuando en España es de día, ¿qué pasa al otro lado de la Tierra?|Quan a Espanya és de dia, què passa a l’altra banda de la Terra?|When it is daytime in Spain, what is happening on the other side of the Earth?', 'Es de noche|És de nit|It is night', ['También es de día|També és de dia|It is also day', 'Es verano siempre|És estiu sempre|It is always summer'], 'Solo la mitad mira al Sol.|Només la meitat mira al Sol.|Only half faces the Sun.'),
  ]),
  '4P-CM-14': lesson(['Consumir de forma responsable es comprar solo lo necesario, elegir productos duraderos y de cercanía, reparar antes de tirar y comparar precios y calidades.|Consumir de manera responsable és comprar només el necessari, triar productes duradors i de proximitat, reparar abans de tirar i comparar preus i qualitats.|Responsible consumption means buying only what you need, choosing long-lasting and local products, repairing before throwing away, and comparing prices and quality.'],
    'Se te rompe una mochila por una costura. ¿Qué haces?|Se’t trenca una motxilla per una costura. Què fas?|Your rucksack splits at a seam. What do you do?', ['Repararla alarga su vida.|Reparar-la allarga la seua vida.|Repairing it extends its life.', 'La coso o la llevo a arreglar antes de comprar otra.|La cus o la porte a arreglar abans de comprar-ne una altra.|I sew it or get it fixed before buying another.'], [
    M('¿Qué producto es «de cercanía»?|Quin producte és «de proximitat»?|Which product is "local"?', 'naranjas de un huerto de tu comarca|taronges d’un hort de la teua comarca|oranges from a farm in your area', ['fruta traída en avión de otro continente|fruita portada en avió d’un altre continent|fruit flown in from another continent', 'un juguete de importación|un joguet d’importació|an imported toy'], 'Viaja menos: contamina menos.|Viatja menys: contamina menys.|It travels less: less pollution.'),
    M('¿Qué compra es más responsable?|Quina compra és més responsable?|Which purchase is more responsible?', 'una botella reutilizable|una botella reutilitzable|a reusable bottle', ['muchas botellas de un solo uso|moltes botelles d’un sol ús|lots of single-use bottles', 'un vaso de plástico cada día|un got de plàstic cada dia|a plastic cup every day'], 'Se usa muchas veces.|S’usa moltes vegades.|It is used many times.'),
    TF('Comprar cosas que no necesitamos genera más residuos.|Comprar coses que no necessitem genera més residus.|Buying things we do not need creates more waste.', true, 'Todo acaba siendo basura.|Tot acaba sent fem.|It all ends up as rubbish.'),
    M('Antes de comprar algo, ¿qué pregunta es útil?|Abans de comprar alguna cosa, quina pregunta és útil?|Before buying something, which question helps?', '¿Lo necesito de verdad?|De veritat ho necessite?|Do I really need it?', ['¿Es el más caro?|És el més car?|Is it the most expensive?', '¿Lo tiene mi amigo?|Ho té el meu amic?|Does my friend have it?'], 'Pensar antes evita gastos inútiles.|Pensar abans evita despeses inútils.|Thinking first avoids waste.'),
    M('La ropa que ya no te vale, ¿qué puedes hacer con ella?|La roba que ja no et va bé, què pots fer amb ella?|What can you do with clothes that no longer fit?', 'Darla a otra persona o a un contenedor de ropa|Donar-la a una altra persona o a un contenidor de roba|Give it to someone or a clothes bank', ['Tirarla a la basura|Tirar-la al fem|Bin it', 'Quemarla|Cremar-la|Burn it'], 'Así tiene una segunda vida.|Així té una segona vida.|It gets a second life.'),
    M('¿Qué es mejor para el planeta?|Què és millor per al planeta?|What is better for the planet?', 'un juguete duradero|un joguet durador|a long-lasting toy', ['un juguete que se rompe enseguida|un joguet que es trenca de seguida|a toy that breaks straight away', 'muchos juguetes baratos que no uso|molts joguets barats que no use|lots of cheap toys I never use'], 'Durar mucho genera menos basura.|Durar molt genera menys fem.|Lasting longer means less waste.'),
  ]),
  '4P-CM-15': lesson(['La huella ecológica mide cuánta naturaleza necesitamos para vivir como vivimos: lo que comemos, la energía que gastamos, cómo viajamos y lo que tiramos.|La petjada ecològica mesura quanta natura necessitem per a viure com vivim: el que mengem, l’energia que gastem, com viatgem i el que tirem.|The ecological footprint measures how much nature we need to live as we do: what we eat, the energy we use, how we travel and what we throw away.', 'Cuanto más gastamos, más grande es la huella. Podemos reducirla con pequeños gestos.|Com més gastem, més gran és la petjada. Podem reduir-la amb xicotets gestos.|The more we use, the bigger the footprint. Small actions can shrink it.'],
    '¿Cómo puedo hacer más pequeña mi huella ecológica?|Com puc fer més xicoteta la meua petjada ecològica?|How can I make my ecological footprint smaller?', ['Gastar menos energía y recursos.|Gastar menys energia i recursos.|Use less energy and fewer resources.', 'Ir andando, ahorrar agua y luz, reciclar y no desperdiciar comida.|Anar a peu, estalviar aigua i llum, reciclar i no malbaratar menjar.|Walk, save water and electricity, recycle and do not waste food.'], [
    M('¿Qué hace más grande la huella ecológica?|Què fa més gran la petjada ecològica?|What makes the ecological footprint bigger?', 'ir siempre en coche aunque sea cerca|anar sempre en cotxe encara que siga prop|always going by car even for short trips', ['ir andando|anar a peu|walking', 'apagar luces|apagar llums|switching off lights'], 'El coche gasta combustible.|El cotxe gasta combustible.|Cars burn fuel.'),
    M('¿Qué alimentos tienen menos huella?|Quins aliments tenen menys petjada?|Which foods have a smaller footprint?', 'frutas y verduras de temporada|fruites i verdures de temporada|seasonal fruit and vegetables', ['comida que viene de muy lejos|menjar que ve de molt lluny|food from very far away', 'productos con mucho envase|productes amb molt d’envàs|heavily packaged food'], 'Necesitan menos transporte y energía.|Necessiten menys transport i energia.|They need less transport and energy.'),
    TF('Tirar comida aumenta la huella ecológica.|Tirar menjar augmenta la petjada ecològica.|Throwing food away increases our footprint.', true, 'Producirla gastó agua, tierra y energía.|Produir-lo va gastar aigua, terra i energia.|Producing it used water, land and energy.'),
    M('¿Qué mide la huella ecológica?|Què mesura la petjada ecològica?|What does the ecological footprint measure?', 'cuánta naturaleza usamos para vivir|quanta natura usem per a viure|how much nature we use to live', ['el tamaño de los pies|la grandària dels peus|shoe size', 'cuánto pesamos|quant pesem|how much we weigh'], 'No es una huella de verdad.|No és una petjada de veritat.|It is not a real footprint.'),
    M('¿Qué gesto reduce la huella en casa?|Quin gest reduïx la petjada a casa?|Which habit shrinks your footprint at home?', 'Bajar un poco la calefacción y abrigarse|Baixar un poc la calefacció i abrigar-se|Turn the heating down a bit and wear a jumper', ['Abrir la ventana con la calefacción puesta|Obrir la finestra amb la calefacció posada|Open the window with the heating on', 'Dejar la tele encendida|Deixar la tele encesa|Leave the TV on'], 'Menos energía, menos huella.|Menys energia, menys petjada.|Less energy, smaller footprint.'),
    M('Para ir a un sitio cercano, ¿qué transporte deja menos huella?|Per a anar a un lloc pròxim, quin transport deixa menys petjada?|For a short trip, which transport leaves the smallest footprint?', 'a pie o en bici|a peu o amb bici|walking or cycling', ['en avión|en avió|by plane', 'en coche solo|en cotxe sol|alone by car'], 'No gastan combustible.|No gasten combustible.|They use no fuel.'),
  ]),
  '4P-CM-16': lesson(['Las tres erres: Reducir (comprar y gastar menos), Reutilizar (dar más usos a las cosas) y Reciclar (separar los residuos para fabricar cosas nuevas).|Les tres erres: Reduir (comprar i gastar menys), Reutilitzar (donar més usos a les coses) i Reciclar (separar els residus per a fabricar coses noves).|The three Rs: Reduce (buy and use less), Reuse (use things again) and Recycle (sort waste to make new things).', 'Contenedores: amarillo (envases de plástico y latas), azul (papel y cartón), verde (vidrio), marrón (restos orgánicos) y gris (el resto).|Contenidors: groc (envasos de plàstic i llandes), blau (paper i cartó), verd (vidre), marró (restes orgàniques) i gris (la resta).|Bins: yellow (plastic packaging and cans), blue (paper and card), green (glass), brown (food waste) and grey (everything else).'],
    '¿Dónde tiras una caja de cereales vacía?|On tires una caixa de cereals buida?|Where does an empty cereal box go?', ['Es de cartón.|És de cartó.|It is cardboard.', 'Al contenedor azul.|Al contenidor blau.|In the blue bin.'], [
    M('¿Dónde va una lata de refresco?|On va una llanda de refresc?|Where does a drinks can go?', 'al contenedor amarillo|al contenidor groc|the yellow bin', ['al verde|al verd|the green bin', 'al azul|al blau|the blue bin'], 'Amarillo: envases de plástico y latas.|Groc: envasos de plàstic i llandes.|Yellow: plastic packaging and cans.'),
    M('¿Dónde va un tarro de mermelada de cristal?|On va un pot de melmelada de vidre?|Where does a glass jam jar go?', 'al contenedor verde|al contenidor verd|the green bin', ['al amarillo|al groc|the yellow bin', 'al marrón|al marró|the brown bin'], 'Verde: vidrio.|Verd: vidre.|Green: glass.'),
    M('¿Dónde van las pieles de fruta?|On van les pells de fruita?|Where does fruit peel go?', 'al contenedor marrón (orgánico)|al contenidor marró (orgànic)|the brown bin (food waste)', ['al azul|al blau|the blue bin', 'al verde|al verd|the green bin'], 'Con ellas se hace abono.|Amb elles es fa adob.|They are made into compost.'),
    M('Usar un bote de cristal como lapicero es…|Usar un pot de vidre com a portallapis és…|Using a glass jar as a pencil pot is…', 'reutilizar|reutilitzar|reusing', ['reciclar|reciclar|recycling', 'reducir|reduir|reducing'], 'Le das un nuevo uso sin transformarlo.|Li dones un nou ús sense transformar-lo.|You give it a new use without changing it.'),
    M('¿Cuál de las tres erres es la más importante?|Quina de les tres erres és la més important?|Which of the three Rs matters most?', 'reducir|reduir|reduce', ['reciclar|reciclar|recycle', 'ninguna|cap|none'], 'Lo mejor es no generar el residuo.|El millor és no generar el residu.|Best of all is not to create the waste.'),
    TF('Las pilas usadas se tiran al contenedor gris.|Les piles usades es tiren al contenidor gris.|Used batteries go in the grey bin.', false, 'Van a un punto de recogida especial: contaminan mucho.|Van a un punt de recollida especial: contaminen molt.|They go to a special collection point: they are very polluting.'),
  ]),
  '4P-CM-17': lesson(['Cuidar el medio ambiente es responsabilidad de todos: familias, escuelas, empresas y ayuntamientos. Cada uno puede aportar algo.|Cuidar el medi ambient és responsabilitat de tots: famílies, escoles, empreses i ajuntaments. Cadascú pot aportar alguna cosa.|Looking after the environment is everyone’s responsibility: families, schools, businesses and town councils. Everyone can do something.'],
    '¿Qué puede hacer la clase para cuidar el medio?|Què pot fer la classe per a cuidar el medi?|What can a class do to care for the environment?', ['Piensa en acciones de cada día.|Pensa en accions de cada dia.|Think of everyday actions.', 'Separar residuos, apagar luces y cuidar el huerto escolar.|Separar residus, apagar llums i cuidar l’hort escolar.|Sort rubbish, switch off lights and look after the school garden.'], [
    M('¿Quién tiene que cuidar el medio ambiente?|Qui ha de cuidar el medi ambient?|Who has to look after the environment?', 'todos|tots|everyone', ['solo los científicos|només els científics|only scientists', 'nadie|ningú|nobody'], 'Es corresponsabilidad.|És corresponsabilitat.|It is a shared responsibility.'),
    M('¿Qué hace un ayuntamiento para cuidar el medio?|Què fa un ajuntament per a cuidar el medi?|What does a town council do for the environment?', 'poner contenedores y carriles bici|posar contenidors i carrils bici|provides bins and cycle lanes', ['tirar basura al río|tirar fem al riu|dumps rubbish in the river', 'cortar todos los árboles|tallar tots els arbres|cuts down all the trees'], 'Organiza servicios para todos.|Organitza serveis per a tots.|It organises services for everyone.'),
    TF('Un niño o una niña no puede hacer nada por el planeta.|Un xiquet o una xiqueta no pot fer res pel planeta.|A child cannot do anything for the planet.', false, 'Los pequeños gestos de muchas personas suman.|Els xicotets gestos de moltes persones sumen.|Small actions by many people add up.'),
    M('En el patio hay papeles en el suelo. ¿Qué es lo mejor?|En el pati hi ha papers en terra. Què és el millor?|There is litter on the playground. What is best?', 'Recogerlos entre todos y tirarlos al contenedor|Arreplegar-los entre tots i tirar-los al contenidor|Pick them up together and put them in the bin', ['Dejarlos|Deixar-los|Leave them', 'Echar más|Tirar-ne més|Drop more'], 'El patio es de todos.|El pati és de tots.|The playground belongs to everyone.'),
    M('¿Qué puede hacer una empresa?|Què pot fer una empresa?|What can a business do?', 'usar menos envases y energía limpia|usar menys envasos i energia neta|use less packaging and clean energy', ['contaminar más|contaminar més|pollute more', 'malgastar agua|malbaratar aigua|waste water'], 'También tienen responsabilidad.|També tenen responsabilitat.|They are responsible too.'),
    M('Una «patrulla verde» en el colegio sirve para…|Una «patrulla verda» a l’escola servix per a…|A "green team" at school is for…', 'recordar a todos que ahorren y reciclen|recordar a tots que estalvien i reciclen|reminding everyone to save and recycle', ['poner multas|posar multes|giving fines', 'pintar las paredes|pintar les parets|painting the walls'], 'Ayuda a crear buenos hábitos.|Ajuda a crear bons hàbits.|It helps build good habits.'),
  ]),
};
export default P;
